// Pull data from both sheets
const outliers = $('Read Outliers Dashboard').all().map(i => i.json);
const yoy      = $('Read YoY Comparison').all().map(i => i.json);

const today = new Date().toLocaleDateString('en-IN', { day:'2-digit', month:'short', year:'numeric', timeZone:'Asia/Kolkata' });

// Filter by flag
const fire    = outliers.filter(r => r['Flag'] === '🔥');
const spark   = outliers.filter(r => r['Flag'] === '⚡');
const growing = outliers.filter(r => r['Flag'] === '📈');
const drop    = outliers.filter(r => r['Flag'] === '📉');

const yoyFire = yoy.filter(r => r['Flag'] === '🔥');
const yoyDrop = yoy.filter(r => r['Flag'] === '📉');

function fmt(rows, cols) {
  if (!rows.length) return '<tr><td colspan="4" style="color:#888">None today</td></tr>';
  return rows.slice(0,10).map(r =>
    `<tr>${cols.map(c => `<td style="padding:4px 10px;border-bottom:1px solid #eee">${r[c] || '-'}</td>`).join('')}</tr>`
  ).join('');
}

const html = `
<html><body style="font-family:Arial,sans-serif;color:#222;max-width:800px;margin:auto;">
<h2 style="background:#111;color:#fff;padding:14px 20px;border-radius:6px">Swiss Beauty - Daily Sales Outliers - ${today}</h2>

<p style="color:#555">Script fetched live Shopify data. Sheet: <a href="https://docs.google.com/spreadsheets/d/1fMV0KVGkq53evsv7mffxmjSwbwDNYVpgq3CRPHkSOZ8">Open Google Sheet</a></p>

<h3>🔥 Confirmed Spikes Today (${fire.length})</h3>
<p style="color:#888;font-size:12px">7D uplift > 100% AND positive across all comparison windows</p>
<table width="100%" cellspacing="0" style="border-collapse:collapse">
  <tr style="background:#f5f5f5"><th style="padding:6px 10px;text-align:left">Product</th><th>Units Today</th><th>Revenue (INR)</th><th>vs 7D</th></tr>
  ${fmt(fire, ['Product','Units Sold Today','Revenue Today (INR)','vs 7D (Units %)'])}
</table>

<h3 style="margin-top:20px">⚡ Recent Burst (${spark.length})</h3>
<p style="color:#888;font-size:12px">Strong 7D spike but weaker in longer windows - short term momentum</p>
<table width="100%" cellspacing="0" style="border-collapse:collapse">
  <tr style="background:#f5f5f5"><th style="padding:6px 10px;text-align:left">Product</th><th>Units Today</th><th>Revenue (INR)</th><th>vs 7D</th></tr>
  ${fmt(spark, ['Product','Units Sold Today','Revenue Today (INR)','vs 7D (Units %)'])}
</table>

<h3 style="margin-top:20px">📈 Growing (${growing.length})</h3>
<p style="color:#888;font-size:12px">Positive uplift in 3+ of 4 time windows</p>
<table width="100%" cellspacing="0" style="border-collapse:collapse">
  <tr style="background:#f5f5f5"><th style="padding:6px 10px;text-align:left">Product</th><th>Units Today</th><th>Revenue (INR)</th><th>vs 7D</th></tr>
  ${fmt(growing, ['Product','Units Sold Today','Revenue Today (INR)','vs 7D (Units %)'])}
</table>

<h3 style="margin-top:20px">📉 Declining Today (${drop.length})</h3>
<p style="color:#888;font-size:12px">Negative uplift in 3+ of 4 time windows</p>
<table width="100%" cellspacing="0" style="border-collapse:collapse">
  <tr style="background:#f5f5f5"><th style="padding:6px 10px;text-align:left">Product</th><th>Units Today</th><th>Revenue (INR)</th><th>vs 7D</th></tr>
  ${fmt(drop, ['Product','Units Sold Today','Revenue Today (INR)','vs 7D (Units %)'])}
</table>

<hr style="margin:30px 0;border:none;border-top:1px solid #eee">
<h3>YoY Highlights</h3>
<table width="100%" cellspacing="0" style="border-collapse:collapse">
  <tr style="background:#f5f5f5"><th style="padding:6px 10px;text-align:left">Product</th><th>This Month Units</th><th>Same Month LY</th><th>Month Uplift</th></tr>
  ${fmt(yoyFire.slice(0,5), ['Product','This Month Units','Same Month LY Units','Month YoY Uplift (Units %)'])}
</table>

<p style="margin-top:30px;color:#aaa;font-size:11px">Auto-generated by Swiss Beauty Sales Outliers automation. Data pulled from Shopify via Bulk Operations API.</p>
</body></html>
`;

return [{ json: { html, today, counts: { fire: fire.length, spark: spark.length, growing: growing.length, drop: drop.length } } }];
